const L = require("./lib"); const N = require("./data");
const { run, p, rich, H1, H1n, H2, H3, pb, bullets, numbered, eq, table, card, callout, figure, NAVY, GREY } = L;
const { fmt0, fmt1, pct } = N;
const F = __dirname + "/figs/";
const E = {}; // equation number registry for cross-reference
const $ = (x) => "$" + fmt0(x);

function partIII() {
  const out = [];
  out.push(H1n("Part III — Model Architecture and Component Mathematics"));
  out.push(H2("8. Architecture overview"));
  out.push(p("The model is a pipeline of separable components (Figure {{F:arch}}). A policy chooses (R, r, day rule), possibly as a function of state. A generator turns that choice into a sequence of dollar outcomes with the declared edge. The Combine state machine consumes outcomes until it passes or fails; on a pass, the XFA state machine consumes further outcomes until the account closes, paying out cash along the way. A fee clock charges subscriptions, activation and payout frictions. Two cross-cutting components sit underneath: the floor convention, which resolves what happens when a trade's stop lies beyond the remaining room, and (for one Stage-2 experiment only) a session time barrier. Analytic bounds derived in Part IV are wired in as run-time oracles."));
  out.push(...figure(F + "fig01_architecture.png", "Model architecture. Boxes are the components implemented in propsim.py (generator, Combine, XFA, fee clock, floor convention), statepolicy.py (policy layer) and timebarrier.py (session barrier). Arrows carry the P&L sequence and the pass event.", { key: "arch" }));
  out.push(p("Each component is deterministic given its inputs except the generator, which is the only source of randomness. This separation is what allows the contract to be validated on scripted outcome sequences (golden-path tests) before any Monte Carlo is run, and it mirrors the project's rule that the rules engine does no randomness and the generator knows nothing about the account."));

  out.push(H2("9. The fair trade generator"));
  out.push(p("A trade risks r dollars to win W = R·r dollars. For the process to be exactly break-even, the win probability must be pinned by R:"));
  out.push(...eq("p = (1 + e) / (1 + R)", [["p", "win probability of a single trade"], ["R", "reward multiple"], ["e", "declared edge, expected P&L per trade as a fraction of r; e = 0 is exact break-even"]])); E.p = L.eqNum();
  out.push(p("Substituting into the expected P&L of one trade confirms the convention:"));
  out.push(...eq("E[X] = p·R·r − (1 − p)·r = e·r", [["X", "dollar outcome of the trade (+W or −r)"], ["r", "dollar risk"]])); E.ev = L.eqNum();
  out.push(p(`Worked example. At R = 2 and e = 0, p = 1/3: a $750 risk wins $1,500 one time in three and loses $750 two times in three, so E[X] = (1/3)(1,500) − (2/3)(750) = 0. At R = 1 and e = 0.05, p = 0.525 and E[X] = 0.05 r. The table below gives p for the grid values of R at e = 0.`));
  out.push(...table(["R:R", "0.5:1", "1:1", "1.5:1", "2:1", "3:1", "5:1", "8:1"], [["p (e = 0)", "66.7 %", "50.0 %", "40.0 %", "33.3 %", "25.0 %", "16.7 %", "11.1 %"]], [1600, 1211, 1211, 1211, 1211, 1211, 1211, 1214], { caption: "Fair win probability implied by the reward multiple", key: "pwin" }));
  out.push(p("This is the single most important design choice in the study: win rate is never a free parameter. It is the price of the R:R, and every profile in the grid is compared at identical expected profit per trade."));

  out.push(H2("10. The Combine state machine"));
  out.push(p("The Combine is a discrete-time process over trading days. Its state after any event is"));
  out.push(...eq("S_C = ( B, F, D, B_d )", [["B", "cumulative balance"], ["F", "current loss floor"], ["D", "today's P&L so far"], ["B_d", "best completed day"]])); E.sc = L.eqNum();
  out.push(p("Within a day, each trade updates the balance and today's P&L, and the breach test is applied after every fill because the firm monitors the limit in real time:"));
  out.push(...eq("B ← B + X,   D ← D + X;   FAIL if B ≤ F", [["X", "the trade's dollar outcome after floor truncation (§11)"]])); E.trade = L.eqNum();
  out.push(p("At the 16:00 CT lock the completed day is recorded, the floor ratchets (never below its old value, never above 0 under the official lock rule), the effective target is recomputed and the pass test is applied:"));
  out.push(...eq("B_d ← max(B_d, D);   F ← min(0, max(F, B − 2000)) ⏎ target_eff = max(3000, B_d / 0.55);   PASS if B ≥ target_eff", [["target_eff", "the profit needed to pass given the best day so far (consistency rule)"], ["0.55", "the consistency fraction: the best day may not exceed 55 % of total profit"]])); E.lock = L.eqNum();
  out.push(...figure(F + "fig02_combine_state_machine.png", "Combine state machine as implemented. Trades act intraday; the ratchet, best-day update and pass test act only at the lock.", { key: "sm" }));
  out.push(p("Two consequences of Eq. (" + E.lock + ") drive everything that follows. A single-day profit above $1,650 raises the target (1,650 / 0.55 = 3,000 exactly), so the largest useful single-day win is $1,650; and because the best day is measured on the day it occurs, a pass can never happen on the same day as the best day — the minimum path is two days, for example +$1,650 then +$1,350. Both facts are pinned by golden-path tests (Appendix D)."));
  out.push(p("Fees: $49 is charged at the start of trading day 0 and every 21 trading days while the Combine is active; $149 on the day of passing. A failed account is treated as a completed attempt (a reset is simply a new attempt at $49, so per-attempt EV is unchanged)."));

  out.push(H2("11. Floor liquidation and the barrier race"));
  out.push(p("The firm liquidates the moment equity touches the floor, including unrealised P&L. A trade whose chosen stop lies beyond the remaining room c = B − F therefore cannot lose r; it can lose at most c, and its win probability is lower than p because price must travel through the floor before it reaches the stop. For a fair continuous path racing a barrier at −c against a target at +W, the probability of reaching the target first depends only on the distances:"));
  out.push(...eq("c = min(r, B − F);   P(win | room c) = c / (c + W)   (e = 0);   outcome = +W or −c", [["c", "effective dollars at risk"], ["W", "unchanged target R·r"]])); E.trunc = L.eqNum();
  out.push(...figure(F + "s_barrier_race.png", "The truncated trade. The stop the trader chose is irrelevant once the floor is nearer; the trade becomes a race between −c and +W.", { key: "race" }));
  out.push(p("Worked example. Risk $1,500 at 1:1 with only $500 of room: c = 500, W = 1,500, P(win) = 500 / 2,000 = 25 % instead of 50 %, and the loss if it loses is $500, not $1,500. Expected P&L is 0.25 × 1,500 − 0.75 × 500 = 0, so the truncated trade is still fair."));
  out.push(p("Three conventions were implemented and compared (Part VI, Finding 1): truncate (above; the contract-faithful default), resize (the trader sizes down to risk c with target R·c and unchanged p; a policy choice, not a contract rule) and none (the project's earlier gate-1.8 run model, which let the trade lose the full r and land below the floor). The last is not a fair model of the contract: it preserves the martingale property by making failures deeper than the contract allows, and it inflates pass probability."));
  out.push(H3("11.1 The zero-edge excursion law (for an MAE-reporting generator)"));
  out.push(p("The project's rules engine liquidates when it is told price touched the floor, and its generator must not know the account balance. The barrier race can therefore be delivered as a per-trade maximum adverse excursion (MAE) drawn from a law that depends only on the trade's own r and W. For a winning trade under a driftless continuous path:"));
  out.push(...eq("P(MAE ≥ c | win) = W (r − c) / ( r (c + W) ),   0 ≤ c ≤ r ⏎ a losing trade has MAE = r", [["MAE", "maximum adverse excursion, the furthest the trade moved against the trader before resolving"]])); E.mae = L.eqNum();
  out.push(p("Derivation. P(touch −c before +W) = W/(c+W); from −c, P(reach +W before −r) = (r−c)/(r+W) by translation invariance; the product divided by P(win) = r/(r+W) gives Eq. (" + E.mae + "). Liquidating whenever MAE ≥ c then reproduces Eq. (" + E.trunc + ") exactly: P(win ∧ MAE < c) = r/(r+W) − W(r−c)/((c+W)(r+W)) = c/(c+W). The sampler inverts the survival function in closed form: c = W·r·(1−u)/(u·r + W) for u uniform on (0, 1). This law has no parameters and no market content; it is a consequence of the same martingale the barrier probabilities rest on, and must not be confused with measured excursion from market data, which is a Stage-2 execution variable."));

  out.push(H2("12. Edge when the floor is closer than the stop"));
  out.push(p("Eq. (" + E.trunc + ") is exact only at e = 0. For the edge ladder a convention is needed for how the edge carries over to a nearer exit. The convention adopted treats the edge as a constant drift per unit variance θ on the price path, fixed by the edge definition at the trade's own stop and target; the floor is then just a closer exit on the same path:"));
  out.push(...eq("p_race(a, b, θ) = (1 − e^{−θa}) / (1 − e^{−θ(a+b)})", [["a", "distance to the lower exit"], ["b", "distance to the upper exit"], ["θ", "2μ/σ², drift per unit variance of the path"]])); E.race = L.eqNum();
  out.push(...eq("p_race(r, W, θ) = (1 + e) / (1 + R)   (solve for θ);   then   P(win | room c) = p_race(c, W, θ)", [["r, W", "the trade's own stop and target"]])); E.theta = L.eqNum();
  out.push(p("θ is found by bisection (bracket ±1/(r+W), doubled until it contains the root; expm1 for both exponentials; raise if (1+e)/(1+R) ∉ (0,1)). Expanding for small θ gives p_race(c,W,θ) ≈ (c/(c+W))(1 + θW/2) and θ ≈ 2e/W, so the expected P&L at the floor is e·c to first order — the simpler 'linear' convention EV = e·c is the first-order expansion of the drift convention. Worked values: r = W = 1,500, e = 0.05 → θ = 6.6722×10⁻⁵ and the two conventions differ in P(win | c = 500) by 1.5×10⁻⁴; r = 1,500, W = 4,500, e = 0.05 → θ = 2.1987×10⁻⁵, difference 1.9×10⁻⁵. Monte-Carlo noise at N = 10⁴ is ≈ 5×10⁻³. The drifted excursion law and the liquidation identity generalise exactly:"));
  out.push(...eq("P(MAE ≥ c | win) = [1 − p_race(c,W,θ)] · p_race(r−c, W+c, θ) / p_race(r,W,θ) ⏎ p_race(r,W,θ) · P(MAE < c | win) ≡ p_race(c,W,θ)", [["≡", "an algebraic identity: with x = e^{−θc}, y = e^{−θW}, z = e^{−θ(r−c)}, (1−xz)(1−xy) − x(1−y)(1−z) = (1−x)(1−xyz)"]])); E.identity = L.eqNum();
  out.push(p("Important distinction for the record. At e = 0 the barrier results are distribution-free (optional stopping on any continuous martingale). At e ≠ 0, Eq. (" + E.race + ") is specific to Brownian motion with constant drift and variance; the convention introduces no parameter but does introduce a process assumption (Assumption A4)."));

  out.push(H2("13. The XFA state machine"));
  out.push(p("The funded account starts at B = 0 with F = −2,000 and pays real cash. Its state adds the payout-window variables:"));
  out.push(...eq("S_X = ( B, F, D, w, N_d, Π, Π_best, paid, Π_since, C )", [["w", "winning days (D ≥ 150) in the current window"], ["N_d", "trading days in the window"], ["Π, Π_best", "window net profit and its best day"], ["paid", "whether any payout has occurred"], ["Π_since", "net profit since the last payout"], ["C", "cumulative cash received"]])); E.sx = L.eqNum();
  out.push(p("Trades update B and D exactly as in Eq. (" + E.trade + ") with closure (not reset) on breach. At the lock:"));
  out.push(...eq("F ← min(0, max(F, B − 2000));   N_d += 1;   Π += D;   Π_since += D ⏎ Π_best ← max(Π_best, D);   w += 1 if D ≥ 150", [])); E.xlock = L.eqNum();
  out.push(p("Payout eligibility is then tested on the path elected at activation (fixed for life):"));
  out.push(...eq("Standard:  w ≥ 5  ∧  (¬paid ∨ Π_since > 0) ⏎ Consistency:  N_d ≥ 3  ∧  Π > 0  ∧  Π_best ≤ 0.4 Π", [["cap", "$2,000 on the Standard path, $3,000 on the Consistency path"]])); E.elig = L.eqNum();
  out.push(...eq("q = min(0.5 B, cap) ⏎ if q ≥ 125:   B ← B − q,   C ← C + 0.9 q − f,   F ← 0,   window ← ∅", [["f", "per-payout processing fee (0 by default; $30 in the friction scenario)"], ["window ← ∅", "w, N_d, Π, Π_best, Π_since reset to 0"]])); E.payout = L.eqNum();
  out.push(p("Two payout policies are used. The zero-edge analysis takes the full allowed amount at eligibility (A5). Part VIII adds a buffer rule, q ← min(q, B − k), which never withdraws below a kept balance k and therefore also delays the first payout until B ≥ k + 125. The engine parameter is keep_balance; with k = 0 the original rule is unchanged, which a golden-path test pins."));
  out.push(p("Worked path (Standard, no frictions). Five days of +$300: B = 1,500 after day 5, floor ratcheted −1,700 → −500 across the five locks, w = 5, eligible; q = min(750, 2,000) = 750; cash 675; B = 750; F → 0. A −$750 day then closes the account at B = 0 = F. This path is one of the golden-path tests. Note what the payout did to the state: the trader now has $750 above a floor of $0 in a fair game, so the most they can ever expect to extract from what remains is $750 (Part IV)."));

  out.push(H2("14. The state-dependent policy layer"));
  out.push(p("A static profile applies the same (R, r, day rule) on every trade. A state-dependent policy is a function π mapping the account state to the next action, evaluated before every trade slot:"));
  out.push(...eq("(R_t, r_t) = π( S_t ),   r_t = 0  ⇒  no trade (day ends)", [["S_t", "the state vector of Eq. (" + E.sc + ") or Eq. (" + E.sx + ") plus the slot index and day index"]])); E.pi = L.eqNum();
  out.push(p("Policies tested: build-then-harvest (trade (R₁, r₁) while B < threshold, then (R₂, r₂)); day-one all-in (risk the full room at R on day one, repeat until B ≥ 2,000 or death, then harvest); k consecutive all-ins; stop-after-payout; and for the Combine, fill-the-gap (risk the smaller of a cap, the consistency-safe win 1,650/R, and the remaining gap to target) and lottery-then-fill. The engine (statepolicy.py) is a per-account vectorised re-implementation of §10 and §13 in which R and r are arrays."));

  out.push(H2("15. The session time barrier (Stage-2 model)"));
  out.push(p("The contract engine has no clock inside a day, so a day-one bet with a $6,000 target resolves as surely as a $150 one. In the live product every position is flattened at 15:10 CT, which is a third exit. To map the funded-side result onto a measurable quantity, timebarrier.py models intra-session P&L of the maximum-size position as a driftless Brownian path with session standard deviation σ_s, racing the floor (stop at −c), the target (+R·c) and the session end:"));
  out.push(...eq("dX = σ_s dB_t,  t ∈ [0, 1] ⏎ exits:  X ≤ −c (liquidated),   X ≥ R·c (won),   t = 1 (flattened at X)", [["σ_s", "session standard deviation of the max-size position's P&L in dollars"], ["s = σ_s / 2000", "the dimensionless ratio reported"]])); E.session = L.eqNum();
  out.push(p("Barrier crossings between discrete steps are detected with the Brownian-bridge probability exp(−2(x₀−b)(x₁−b)/σ²Δt), which makes hitting probabilities exact for a continuous path at any step size (200 steps per session are used only to locate the flatten P&L). If the session ends without resolution the account carries X into the lock, ratchets per Eq. (" + E.xlock + "), and repeats the all-in on the new room the next day, until B ≥ 2,000 (the floor is then locked at 0 and the harvest recovers the balance) or the account dies. Expected net is 0.9 × harvest efficiency × E[B | resolved] × P(resolved), with harvest efficiency measured from the binary engine (1.000 without frictions, 0.952 with)."));
  return out;
}

function partIV() {
  const out = [];
  out.push(H1n("Part IV — Analytic Bounds and Exact Results"));
  out.push(p("Before any simulation, three facts follow from the martingale property of the balance under a fair process. They bound what any policy can achieve, they locate where value is lost, and they are enforced on every Monte-Carlo run as oracles: a result outside them is an engine error, never a finding."));
  out.push(H2("16. The Combine ceiling: P(pass) ≤ 2/5"));
  out.push(p("Under e = 0 every trade has zero expected P&L, so the balance B is a martingale. The Combine stops at a pass or a fail after a finite number of bounded steps, so optional stopping gives E[B_τ] = 0. At a pass B ≥ 3,000; at a fail B = F ≥ −2,000 (the floor is never below its starting value, and liquidation lands exactly on it). Hence"));
  out.push(...eq("0 = E[B_τ] ≥ 3000·P(pass) − 2000·(1 − P(pass))   ⇒   P(pass) ≤ 2000 / 5000 = 2/5", [["τ", "the stopping time (pass or fail)"]])); E.ceiling = L.eqNum();
  out.push(p("The ceiling is attained only if every pass lands exactly on 3,000 and every fail on −2,000. Three features of the contract pull real profiles below it: overshoot (a $500 bet from +2,700 wastes $200 of expectation), the ratchet (fails at a floor above −2,000), and the consistency rule (passes above 3,000). Everything a profile can do is choose how far below 2/5 it lands. This is the reason pass probability turned out to be a weak discriminator between profiles (H2)."));
  out.push(H2("17. The XFA ceiling and the leak identity"));
  out.push(p("Let Q be cumulative gross payouts and T = B + Q. A trade changes B by a zero-mean amount; a payout moves q from B to Q; so T is a martingale starting at 0 and bounded below by −2,000. By Fatou's lemma at the closure time, E[T_τ] ≤ 0, and at closure B = F ∈ [−2,000, 0]:"));
  out.push(...eq("E[Q] = E[T_τ] − E[F_τ] ≤ −E[F_τ] ≤ 2000", [["F_τ", "the floor at closure: −2,000 minus any ratchet, or 0 after a payout"]])); E.xceil = L.eqNum();
  out.push(p("In words: the firm lets the trader lose up to $2,000 of simulated money for free, and in a fair game the expected amount one can walk away with equals the expected amount one is allowed to lose for free. Every rule that shrinks the free loss (the ratchet; the jump to 0 after the first payout) shrinks expected extraction one for one. Writing −E[F_τ] out over the two kinds of closure (no payout yet, floor at −2,000 + ratchet; after a payout, floor 0) gives the identity that organises the funded-side results:"));
  out.push(...eq("E[Q] = ( 1 − P(payout) ) × ( 2000 − E[ratchet | no payout] )", [["ratchet", "how far the floor had risen above −2,000 on a path that died without ever paying out"]])); E.leak = L.eqNum();
  out.push(p(`Worked example on the best static profile (2:1, $750, one trade a day; results_state_policy_xfa.csv, N = 20,000): P(payout) = ${pct(N.sp("static 2:1 $750").p_payout, 1)}, E[Q] = $${fmt0(N.sp("static 2:1 $750").gross)}. Solving Eq. (${E.leak}): 2000 − E[ratchet] = ${fmt0(N.sp("static 2:1 $750").gross / (1 - N.sp("static 2:1 $750").p_payout))}, so losing paths had on average $${fmt0(2000 - N.sp("static 2:1 $750").gross / (1 - N.sp("static 2:1 $750").p_payout))} of cushion eaten by the ratchet before they died. That is the leak, and it is the quantity the funded-side policy must minimise.`));
  out.push(H2("18. The day-one all-in identity"));
  out.push(p("The ratchet only moves at a lock, so a losing path that dies before any lock has raised the floor contributes the full $2,000 to −E[F_τ]. The policy that maximises that probability risks the entire room on the first trade at multiple R. With probability R/(1+R) it loses and dies at −2,000 with zero ratchet; with probability 1/(1+R) it wins, the balance is 2,000R, and after the lock the floor is 0. From there the harvest is a fair game absorbed at 0 whose total expected payout equals the starting balance provided the account is run to closure (verified: P(closed) = 1.000 and unrealised balance ≈ 0 in every run). Therefore"));
  out.push(...eq("E[Q] = 2000·R/(1+R);   E[net] = 0.9 × 2000·R/(1+R) → 1800 as R → ∞", [])); E.allin = L.eqNum();
  out.push(p("The identity is an expectation over the account's whole life, not cash in hand after the first payout. Each payout is capped at 50 % of the balance and at $2,000, so the balance comes out in pieces. At R = 2 the winning account holds $4,000: the first payout is typically $2,000 gross ($1,800 net; exactly that in 64 % of winning accounts, mean $1,726) around trading day 8. The remaining ≈ $2,000 is then both the account's entire drawdown room (the floor is $0 after a payout) and still withdrawable; in expectation it yields a further ≈ $1,870 net over about 3 more payouts, and the account closes around trading day 42 (90 % by day 60). Total net per winning account averages $3,598 (10th–90th percentile $2,531–$4,736) = 0.9 × $4,000 (bankroll/payout_trace.py, N = 200,000, validated against the engine)."));
  out.push(p("Worked example, R = 3: P(lose) = 3/4, E[Q] = 1,500, E[net] = 1,350. Measured at N = 100,000: $" + fmt0(N.allin[3]) + " ± " + fmt0(N.allinSE[3]) + " (results_final.csv). Nothing about the harvest — bet size, trades per day, horizon — enters the identity, and the simulation confirms it does not enter the result (Part VI). The identity also explains why 'build then harvest' policies with a partial first bet only reshape the distribution: a $1,000 first bet at 2:1 loses to a −1,000 balance, survives, and the next lock or the next win begins the ratchet leak."));
  out.push(H2("19. Exact Markov chain for the recommended Combine profile"));
  out.push(p("For the static profile 1:1, $1,500, one trade per day, the Combine visits only four transient states before absorption, so P(pass) can be solved exactly (Figure {{F:markov}}). In $500 units the cushion is 4, the target 6 and the bet 3; the truncation rule turns a bet from one unit of room into a one-unit bet at p = 1/4 (Eq. " + E.trunc + ")."));
  out.push(...figure(F + "fig09_markov_16_49.png", "The four reachable states and their transitions. A trade from state B' or C has only $500 of room, so it risks $500 to win $1,500 at p = ¼.", { key: "markov" }));
  out.push(...eq("a = ½ + ½c,   c = ¼a,   d = ½a + ½b′,   b′ = ¼d ⏎ ⇒   a = 4/7,   d = P(pass) = 16/49 ≈ 0.32653", [["a, b', c, d", "pass probabilities from states A, B', C and the start D"]])); E.markov = L.eqNum();
  out.push(p("Solution. From a = ½ + ⅛a, a = 4/7. Then d = 2/7 + ⅛d, so (7/8)d = 2/7 and d = 16/49. The balance check of fair-game conservation: pass mass 16/49 at +3,000 (+48,000/49); fail mass 21/49 at −2,000 (from B') and 12/49 at −500 (from C) (−42,000/49 − 6,000/49); total 0. Two observations: the consistency rule never binds on this profile (1,500/0.55 = 2,727 < 3,000), so the profile sits exactly on the H3 ridge; and the Combine floor lock never binds (balance never exceeds $1,500 before the passing trade), so 16/49 holds with or without the rule correction."));
  out.push(H3("19.1 Is 16/49 optimal? The supremum over all fair strategies"));
  out.push(p("The Monte-Carlo search in Part VI tried eight state-dependent policies and none beat 16/49, but that is an empirical statement about the policies tried. To make it a statement about all strategies, note that within one day a continuous fair process can end at any distribution of balances with the right mean that stays at or above the floor (ending at the floor is a fail). The best achievable pass probability from a lock state is therefore the concave envelope, over end-of-day balances x, of the value of the next lock state:"));
  out.push(...eq("V(B, F, B_d) = cav_x [ g(x) ](B) ⏎ g(x) = 0 if x ≤ F;   1 if x passes;   V(post-lock state) otherwise", [["cav_x", "upper concave envelope in the end-of-day balance x, evaluated at the current balance B, over x ≥ F (or x ≥ max(F, B − 1,000) with a daily loss limit, where ending at B − 1,000 is a forced flat, not a failure)"], ["post-lock state", "(x, min(0, max(F, x − 2000)), max(B_d, x − B))"]])); E.supremum = L.eqNum();
  out.push(p(`Value iteration from V = 0 converges to the least fixed point, which is the supremum over all strategies. On a $50 balance grid the result is ${N.sup(50, 0).sup_p_pass.toFixed(6)}, equal to the two-day bound 2000²/((2000+X)(5000−X)) at X = $1,350 or $1,650 — close day one at +$1,350 or +$1,650 risking the full $2,000, then race the remainder. 16/49 = 0.326531 is 0.06 points below. Coarser grids give ${N.sup(500, 0).sup_p_pass.toFixed(6)} ($500) and ${N.sup(100, 0).sup_p_pass.toFixed(6)} ($100), each exactly the two-day formula at the best grid point; multi-day strategies add nothing (convergence in four daily steps), and widening the state space changes nothing. With the optional $1,000 daily loss limit the supremum is unchanged (${N.sup(50, 1000).sup_p_pass.toFixed(6)}); the same value is reached over more days because a losing day does not ratchet the floor. The solver's first version returned exactly 0.4: it let end-of-day mass sit below the floor. The ceiling oracle caught the error, which is the same overshoot as Finding 1. A Monte-Carlo run of the supremum policy (N = 1,000,000, prediction recorded beforehand) first failed its 3-SE check at z = +3.15; the failure protocol (§23.1) traced it to chance, and five further seeds pooled to z = +1.13 (optimality/results_t4_check2_propsim.txt).`));
  return out;
}

function partV() {
  const out = [];
  out.push(H1n("Part V — Computational and Validation Methodology"));
  out.push(H2("20. Monte-Carlo design"));
  out.push(p("All experiments run N independent accounts in lockstep as numpy arrays: each trading day, each trade slot draws one uniform per live account, applies the outcome (after floor truncation), tests the breach, and at the lock applies Eqs. (" + E.lock + ") or (" + E.xlock + ")–(" + E.payout + "). Every run is seeded; the seed for each cell is recorded in its result file, and the comparison experiments (floor modes, edge conventions) share seeds across arms so differences are paired, not independent. Reported statistics are means over accounts with standard errors:"));
  out.push(...eq("SE(p̂) = √( p̂(1 − p̂) / N ),   SE(x̄) = s_x / √N", [["p̂", "a sample probability (pass, payout, net > 0)"], ["x̄, s_x", "sample mean and standard deviation of a cash quantity"]])); E.se = L.eqNum();
  out.push(p("Sample sizes: 10,000 per cell for the 160-cell grid (SE of a pass probability ≈ 0.005; of net per attempt ≈ $10–19); 15,000–20,000 for the sweeps; 100,000 for the final profiles (SE of net ≈ $3–11); 2,000,000 for the exact-chain check (SE 0.00033)."));
  out.push(H3("20.1 Exact chain at positive edge"));
  out.push(p("For Part VIII the Combine stage is computed exactly rather than simulated. For a static one-trade-per-day profile the post-lock state (B, F, B_d) takes finitely many values, and probability mass is propagated day by day: a trade with room c ≥ r wins +W with p = (1+e)/(1+R); with c < r it wins with p_race(c, W, θ) (Eq. {{E:race}}) and otherwise liquidates at the floor. The lock applies Eq. {{E:lock}}. Propagation stops when unresolved mass is below 10⁻¹³, giving P(pass), E[days] and E[subscriptions] exactly. The chain reproduces 16/49 to 1.7 × 10⁻¹⁴ and is checked against Monte Carlo at every profile and edge (Part VIII)."));
  out.push(H2("21. Output metrics"));
  out.push(p("For the Combine: P(pass), P(fail), mean trading days, mean subscription fees, mean terminal balance (martingale check). For the XFA: P(any payout), mean net cash 0.9·Q − f·n_pay, mean gross Q, payouts per account, days to first payout, P(closed), mean of B + Q (Fatou check). Expected net cash per Combine attempt combines them:"));
  out.push(...eq("EV_attempt = P(pass) × ( X_net − 149 ) − S_sub", [["X_net", "expected net cash per XFA for the chosen funded profile"], ["S_sub", "expected subscription dollars per attempt (≥ 49)"]])); E.evatt = L.eqNum();
  out.push(p(`Worked example (zero edge, Part VI): with the exact pass probability 16/49, the exact expected subscription $49.00 and X_net = ${$(N.allin[3])} (3:1 day-one all-in), EV = 0.32653 × (${fmt0(N.allin[3])} − 149) − 49 = ${$(N.evExact(N.allin[3]))}.`));
  out.push(p("The extraction ratio (expected cash returned per dollar of fees at risk) is also recorded: (S_sub + P(pass)·149 + EV) / (S_sub + P(pass)·149)."));
  out.push(H2("22. Experiment register"));
  out.push(...table(["Script → result file", "What it varies", "Held fixed", "N", "Feeds"], [
    ["run_grid.py → results_grid_edge0.csv, results_edge_ladder.csv", "R ∈ {0.5,1,1.5,2,3} × r ∈ {50…1500} × 4 day rules × 2 payout paths", "e = 0; truncate; official floor lock", "10,000", "Finding 2, H1–H3"],
    ["run_floor_modes.py → results_floor_mode_504.csv", "floor convention none / truncate / resize on 9 cells, 504-day continuous lifecycle", "e = 0", "20,000 (paired)", "Finding 1"],
    ["run_edge_convention.py → results_edge_convention.csv", "edge convention drift vs linear, 5 cells × 6 edges", "truncate", "10,000 (paired)", "Finding 4"],
    ["run_consistency_sweep.py → results_consistency_sweep.csv", "consistency fraction {0.40, 0.55, 0.70, 1.00} × R × r up to $2,000", "1/day; e = 0", "15,000", "Finding 5 (H3)"],
    ["statepolicy.py runs → results_state_policy_*.csv", "state-dependent policies, Combine and XFA", "e = 0; truncate", "20,000–40,000", "Finding 6 (H4)"],
    ["timebarrier.py → results_timebarrier.csv", "s ∈ {0.25…8} × R for the day-one all-in", "e = 0", "20,000", "Finding 8"],
    ["run_final.py → results_final.csv", "final profiles × edge ladder × frictions", "truncate; drift", "100,000", "Final results, Part VII"],
    ["make_figs.py → fig13_stats.csv", "net-per-attempt distribution of the recommended combined policy", "e = 0", "50,000", "Figure {{F:dist}}"],
    ["run_exact_chain_check.py → results_exact_chain_check.csv", "16/49 check", "e = 0", "2,000,000", "§19"],
    ["optimality/combine_supremum.py → results_combine_supremum.csv", "supremum over all strategies, with/without DLL", "grid $500–$50", "exact DP", "§19.1"],
    ["optimality/dll_funded.py, results_horizon_frictions.csv", "DLL cap doubling; XFA horizon with frictions", "e = 0", "100,000", "Finding 7"],
    ["edge/value_of_edge.py (pre-registered) → results_*_edge.csv", "10 profiles × 6 edges, both stages, both payout paths", "conduct constraints", "exact + 200,000 / 50,000", "Part VIII"],
    ["edge/*_exploratory.py → results_payout_*.csv", "small funded risks; payout fraction and buffer", "e = 0–0.20", "40,000–50,000", "Part VIII (exploratory)"],
  ], [3200, 2900, 1500, 1000, 1480], { caption: "Experiment register", key: "register", size: 17 }));
  out.push(H2("23. Validation architecture"));
  out.push(p("Thirty-three automated tests (test_propsim.py) run before any result is reported. They fall into four families:"));
  out.push(...bullets([
    "Golden paths from the rule text: scripted outcome sequences with hand-computed end states (two-day minimal pass; single-day $3,000 does not pass and floor locks at 0; best-day trap needs $5,455; trailing floor kills at zero; intraday breach before the lock; subscription billing on days 0 and 21; XFA first payout and floor jump; winning-day threshold at $150; payout minimum; caps; consistency path; window restart; payout fee and net-positive rule).",
    "Analytic oracles under Monte Carlo: P(pass) ≤ 0.40 + 4 SE and |E[B_τ]| < $60 for four profiles at N = 20,000; E[gross] ≤ $2,000 and E[B + Q] ≤ $80 for three XFA profiles.",
    "Exact identities: the four-state Markov chain (N = 200,000 within 3 SE of 16/49); the no-floor artifact reproduces 4/9 exactly; the liquidation identity Eq. (" + E.identity + ") to 10⁻¹² over 300 (r, W, c, θ) combinations; θ solver reproduces (1+e)/(1+R) at the trade's own stop to 10⁻¹⁰ and pins the spot value θ = 2.1987×10⁻⁵.",
    "Sampler checks: the excursion law at θ = 0 and θ ≠ 0 reproduces c/(c+W) and p_race(c,W,θ) within 0.4 % at four rooms, N = 400,000 (the only tests exercising the bisection inverse).",
  ]));
  out.push(H3("23.1 Pre-registration and the failure protocol"));
  out.push(p("The Part VIII study and every check added after the audit were pre-registered: profiles, edges, metrics and pass/fail criteria were written to a file before any run (edge/PREREG_T5.md). A failed pre-registered check is kept on record and diagnosed in four steps — audit of terminal states, decomposition by stage, test of the component in isolation, replication with seeds fixed before running — and is never rerun until it passes. Analyses chosen after seeing results are labelled exploratory and reported separately."));
  out.push(p("The methodological rule throughout was that the deterministic contract machine had to be validated on scripted paths before any random experiment was trusted, and that any Monte-Carlo result outside an analytic bound is treated as a bug. That rule is what caught Finding 1."));
  return out;
}

module.exports = { partIII, partIV, partV, E };
